struct MockTransport { inbox: Vec<Vec<u8>>, sent: Vec<Vec<u8>> }
#[async_std::test]
async fn execute_request_replies_ok_and_preserves_state() {
    let conn = ConnectionFile::sample();
    let t = MockTransport::scripted(&[
        wire::execute_request("x = 1"),
        wire::execute_request("x + 1"),
    ]);
    let kernel = Kernel::new(t, conn);
    let replies = kernel.run_scripted().await.expect("run");
