}

#[test]
fn server_handshake_and_did_open_publish_diagnostics() {
    let (conn, client) = lsp_server::Connection::memory();
    let handle = std::thread::spawn(move ||
        buff_lsp::server::run_stdio_like(conn).expect("server loop"));
    client.send(lsp_types::InitializeParams::default_params())?;
    client.notify(did_open("func main():\n    let x: Int = \"s\"\n"));
    let diags = client.wait_notification("textDocument/publishDiagnostics")?;
    assert!(!diags.diagnostics.is_empty());
    handle.join().expect("clean exit");
}

